"""Derive SkyyGear/build_skyygear_0.3.49.py from the GENERATED SkyyGear 0.3.48 (build_skyygear_0.3.48.py = the SET pin, itself GENERATED by
tools/gear_0_3_48_patch.py - edit the patch, never a generated script). Every anchor is asserted once; at the end every change is undone on a
copy and compared with 0.3.48 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/gear_0_3_49_patch.py   then   python SkyyGear/build_skyygear_0.3.49.py   (never --deploy)
      then  python SkyyGear/test_skyygear_0.3.49.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.3.49 (2026-10-27) = HOTFIX capfix: A TIER-UP THAT GIVES CHANGE FAILED FOR A PLAYER WITHOUT A BACKPACK. Skyy (in game, Crafting > Upgrade, Iron
  Watering Can -> Bronze, every requirement green: Farming Lv 15, Carrot collection II, Furnace Charm I, Bronze Ingot 32, Carrot 355, Stick 150):
  the page said "Something went wrong - nothing was changed. Click Refresh."; the server log, once per click: "[SkyyGear] tools page click
  failed: java.lang.IllegalArgumentException: Capacity is less than or equal zero! 0 <= 0".
  ROOT CAUSE (0.3.48, not SkyySacks 0.8.32): GearUp.roomWhy - the "does the change fit" check 0.3.48 added for Enchanted items paying a tier-up -
  copies storage / hotbar / backpack into new SimpleItemContainer(cs[i].getCapacity()). A player with no backpack has the engine's
  EmptyItemContainer (capacity 0) there, and the engine's SimpleItemContainer refuses capacity 0 with exactly that message. It runs only when an
  opened Enchanted item gives change (Skyy's sticks / carrots / bronze), BEFORE anything moves, so the throw reached LifePage.handleDataEvent's
  catch: nothing was taken (verified in the harness). The 0.3.48 harness built every backpack with 9 slots, so it never saw it.
  1. GearUp.roomWhy: a section with capacity 0 (no backpack) is skipped - it holds nothing and takes nothing, so no copy is made for it.
  2. GearArmor.activeCopy (the same pattern on the armor container): never a 0-capacity copy (1 slot when the container has none - empty, so
     the stats it gives are the same as none).
  GearUp.giveChange already reads a capacity-0 section safely (0 slots; addItemStack inside a try) - unchanged.
  Pages / commands / systems / Server Setup rows: none. SAVED DATA: none (no migration).
  ROLLBACK to 0.3.48: safe alone (tier-ups that give change fail again for players without a backpack; nothing is ever taken).
'''

P = G.Patch(os.path.join(ROOT, "SkyyGear", "build_skyygear_0.3.48.py"), os.path.join(ROOT, "SkyyGear", "build_skyygear_0.3.49.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.3.48"') and P.has("public static String roomWhy(") and not P.has("0.3.49 (capfix)"), "not the generated SkyyGear 0.3.48 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("mk(\"")

P.rep('''"""SkyyGear 0.3.48 - build script (javassist via jpype). GENERATED by tools/gear_0_3_48_patch.py from the SET pin 0.3.47 (itself GENERATED by
tools/gear_0_3_47_patch.py) - edit the patch, never this file. Run: python SkyyGear/build_skyygear_0.3.48.py -> SkyyGear/SkyyGear-0.3.48.jar
(never --deploy). Harness: python SkyyGear/test_skyygear_0.3.48.py.

''', '''"""SkyyGear 0.3.49 - build script (javassist via jpype). GENERATED by tools/gear_0_3_49_patch.py from the SET pin 0.3.48 (itself GENERATED by
tools/gear_0_3_48_patch.py) - edit the patch, never this file. Run: python SkyyGear/build_skyygear_0.3.49.py -> SkyyGear/SkyyGear-0.3.49.jar
(never --deploy). Harness: python SkyyGear/test_skyygear_0.3.49.py.

''' + NOTE + '''
0.3.48 notes (SkyyGear 0.3.48 - generated by tools/gear_0_3_48_patch.py from the SET pin 0.3.47; harness test_skyygear_0.3.48.py):
''')
P.rep('VERSION = "0.3.48"\n', 'VERSION = "0.3.49"\n')

# 1. roomWhy: no copy of a capacity-0 section (EmptyItemContainer = no backpack); the engine's SimpleItemContainer refuses capacity 0
P.rep('''  for (int i = 0; i < cs.length; i++) {
    if (cs[i] == null) continue;
    @SIC@ c = new @SIC@(cs[i].getCapacity());''', '''  for (int i = 0; i < cs.length; i++) {
    if (cs[i] == null || cs[i].getCapacity() <= 0) continue;          // 0.3.49 (capfix): no backpack = capacity 0 - nothing to copy (SimpleItemContainer(0) throws)
    @SIC@ c = new @SIC@(cs[i].getCapacity());''')
# 2. activeCopy: the same pattern on the armor container - never a 0-capacity copy
P.rep('''  short cap = armor.getCapacity();
  @SIC@ c = new @SIC@(cap);''', '''  short cap = armor.getCapacity();
  @SIC@ c = new @SIC@(cap > 0 ? cap : (short) 1);          // 0.3.49 (capfix): never a 0-capacity container (an empty slot = the same stats)''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("mk(\"") == CLS0, "0.3.49: no class / command / system"
assert P.s.count("new @SIC@(") == 2 and "new @SIC@(cs[i].getCapacity())" in P.s, "0.3.49: the two dynamic SimpleItemContainer copies are the ones guarded"
P.finish()
